import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";

test.describe("Flow lifecycle events", () => {
  test.describe.configure({ timeout: 180_000 });

  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("Flow interruption events appear in log and timeline shows Interrupted status", async ({
    inspectorPage,
  }) => {
    await flows.flowLifecycle.triggerFlowInterruptionAndAssertEvents(inspectorPage);
    await flows.flowLifecycle.assertInterruptedFlowInTimeline(inspectorPage);
  });
});
